--
-- Name: acs_message__edit(integer, character varying, character varying, character varying, text, integer, timestamp with time zone, integer, character varying, boolean); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.acs_message__edit(integer, character varying, character varying, character varying, text, integer, timestamp with time zone, integer, character varying, boolean) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
    p_message_id    alias for $1;
    p_title         alias for $2;    -- default null
    p_description   alias for $3;    -- default null
    p_mime_type     alias for $4;    -- default 'text/plain'
    p_text          alias for $5;    -- default null
    p_data          alias for $6;    -- default null
    p_creation_date alias for $7;    -- default sysdate
    p_creation_user alias for $8;    -- default null
    p_creation_ip   alias for $9;    -- default null
    p_is_live       alias for $10;   -- default 't'
    v_revision_id cr_revisions.revision_id%TYPE;
begin
    -- create a new revision using whichever call is appropriate
    if p_data is not null then
		-- need to take care of blob?
        v_revision_id := content_revision__new (
            p_message_id,		-- item_id        
            p_title,			-- title          
            p_description,		-- description    
            p_data,			-- data           
            p_mime_type,		-- mime_type      
            p_creation_date,		-- creation_date  
            p_creation_user,		-- creation_user  
            p_creation_ip		-- creation_ip    
        );
    else if p_title is not null or p_text is not null then
        v_revision_id := content_revision__new (
            p_title,			-- title          
            p_description,		-- description    
			now(),		-- publish_date
            p_mime_type,		-- mime_type      
			null,		-- nls_language
            p_text,			-- text           
            p_message_id,		-- item_id        
			null,		-- revision_id
            p_creation_date,		-- creation_date  
            p_creation_user,		-- creation_user  
            p_creation_ip		-- creation_ip    
        );      
    end if;
	end if;

    -- test for auto approval of revision   
    if p_is_live then 
        perform content_item__set_live_revision(v_revision_id);
    end if;

    return v_revision_id;
end;$_$;


