--
-- Name: acs_object__new(integer, character varying, timestamp with time zone, integer, character varying, integer, character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.acs_object__new(integer, character varying, timestamp with time zone, integer, character varying, integer, character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
