--
-- Name: acs_object_util__object_type_p(integer, character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.acs_object_util__object_type_p(integer, character varying) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $_$
declare
    p_object_id         alias for $1;
    p_object_type       alias for $2;
    v_exist_p           boolean := 'f';
begin
    v_exist_p := acs_object_util__object_ancestor_type_p(p_object_id, p_object_type);
    return v_exist_p;
end;$_$;


ALTER FUNCTION public.acs_object_util__object_type_p(integer, character varying) OWNER TO simone;

--
-- Name: acs_object_util__type_ancestor_type_p(character varying, character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.acs_object_util__type_ancestor_type_p(character varying, character varying) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $_$
declare
    p_object_type1      alias for $1;
    p_object_type2      alias for $2;
begin

    if not acs_object_util__object_type_exist_p(p_object_type1) then
        raise exception 'Object type % does not exist', p_object_type1;
    end if;

    if not acs_object_util__object_type_exist_p(p_object_type2) then
        raise exception 'Object type % does not exist', p_object_type2;
    end if;
        
    return exists (select 1
                   from acs_object_types o1, acs_object_types o2
                   where p_object_type2 = o2.object_type
                     and o1.object_type = p_object_type1
                     and o1.tree_sortkey between o2.tree_sortkey and tree_right(o2.tree_sortkey));
end;$_$;


ALTER FUNCTION public.acs_object_util__type_ancestor_type_p(character varying, character varying) OWNER TO simone;

