--
-- Name: acs_user__new(integer, character varying, timestamp with time zone, integer, character varying, integer, character varying, character varying, character varying, character varying, character varying, character, character, character varying, boolean, integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.acs_user__new(integer, character varying, timestamp with time zone, integer, character varying, integer, character varying, character varying, character varying, character varying, character varying, character, character, character varying, boolean, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
    p_user_id                  alias for $1;  -- default null  
    p_object_type              alias for $2;  -- default 'user'
    p_creation_date            alias for $3;  -- default now()
    p_creation_user            alias for $4;  -- default null
    p_creation_ip              alias for $5;  -- default null
    p_authority_id             alias for $6;  -- defaults to local authority
    p_username                 alias for $7;  --
    p_email                    alias for $8;  
    p_url                      alias for $9;  -- default null
    p_first_names              alias for $10;  
    p_last_name                alias for $11;  
    p_password                 alias for $12; 
    p_salt                     alias for $13; 
    p_screen_name              alias for $14; -- default null
    p_email_verified_p         alias for $15; -- default 't'
    p_context_id               alias for $16; -- default null
    v_user_id                  users.user_id%TYPE;
    v_authority_id             auth_authorities.authority_id%TYPE;
    v_person_exists            varchar;			
begin
    v_user_id := p_user_id;

    select case when count(*) = 0 then 'f' else 't' end into v_person_exists
    from persons where person_id = v_user_id;

    if v_person_exists = 'f' then
        v_user_id := person__new(
            v_user_id, 
            p_object_type,
            p_creation_date, 
            p_creation_user, 
            p_creation_ip,
            p_email, 
            p_url, 
            p_first_names, 
            p_last_name, 
            p_context_id
        );
    else
     update acs_objects set object_type = 'user' where object_id = v_user_id;
    end if;

    -- default to local authority
    if p_authority_id is null then
        select authority_id
        into   v_authority_id
        from   auth_authorities
        where  short_name = 'local';
    else
        v_authority_id := p_authority_id;
    end if;

    insert into users
       (user_id, authority_id, username, password, salt, screen_name, email_verified_p)
    values
       (v_user_id, v_authority_id, p_username, p_password, p_salt, p_screen_name, p_email_verified_p);

    insert into user_preferences
      (user_id)
      values
      (v_user_id);

    return v_user_id;
  
end;$_$;


ALTER FUNCTION public.acs_user__new(integer, character varying, timestamp with time zone, integer, character varying, integer, character varying, character varying, character varying, character varying, character varying, character, character, character varying, boolean, integer) OWNER TO simone;

