--
-- Name: ah_edit_num(double precision, integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.ah_edit_num(double precision, integer) RETURNS character varying
    LANGUAGE plpgsql
    AS $_$
declare
   nume       alias for $1;
   deci       alias for $2;
   ws_max_val float := 999999999999999.9999999999;
   ws_min_val float := -99999999999999.9999999999;
   risultato  varchar;
   edit_deci  varchar;
begin
   if deci > 10
   then
      return 'Error: max 10 decimali';
   end if;

   if nume > ws_max_val
   or nume < ws_min_val
   then
      return 'Error: max 14 cifre intere';
   end if;

   if deci < 1
   or deci is null
   then
      edit_deci := '';
   else
      edit_deci := 'd'||rpad('0',deci,'0');
   end if;

   risultato := to_char(nume, '999g999g999g999g990'||edit_deci);
   risultato := translate (risultato,',','!');
   risultato := translate (risultato,'.',',');
   risultato := translate (risultato,'!','.');
   risultato := trim (risultato);

   return risultato;

end;$_$;


ALTER FUNCTION public.ah_edit_num(double precision, integer) OWNER TO simone;

