-- Name: category_synonym__del(integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.category_synonym__del(integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
-- delete synonym
declare
	p_synonym_id	alias for $1;
begin
	-- delete search results
	delete	from category_search_results
	where	synonym_id = p_synonym_id;

	-- delete synonym index
	delete	from category_synonym_index
	where	synonym_id = p_synonym_id;

	-- delete synonym
	delete	from category_synonyms
	where	synonym_id = p_synonym_id;

	return (1);
end;$_$;


