--
-- Name: category_synonym__edit(integer, character varying, character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.category_synonym__edit(integer, character varying, character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
	p_synonym_id	alias for $1;
	p_new_name	alias for $2;
	p_locale	alias for $3;
begin
	-- update synonym data
	update	category_synonyms
	set	name = p_new_name,
		locale = p_locale
	where	synonym_id = p_synonym_id;

	-- update synonym index and search results
	PERFORM category_synonym__reindex (p_synonym_id, p_new_name, p_locale);

	return (p_synonym_id);
end;$_$;


ALTER FUNCTION public.category_synonym__edit(integer, character varying, character varying) OWNER TO simone;

--
-- Name: category_synonym__edit_cat_trans_trg(); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.category_synonym__edit_cat_trans_trg() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
-- trigger function for updating a category translation
declare
    v_synonym_id    integer;
begin
	-- get synonym_id of updated category translation
    select synonym_id into v_synonym_id
    from   category_synonyms
    where  category_id = OLD.category_id
           and name = OLD.name
           and locale = OLD.locale
           and synonym_p = 'f';

	-- update synonym
    PERFORM category_synonym__edit (v_synonym_id, NEW.name, NEW.locale);

    return new;
end;$$;


