--
-- Name: category_synonym__get_similarity(integer, integer, bigint); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.category_synonym__get_similarity(integer, integer, bigint) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
-- calculates similarity of two strings
declare
	p_len1		alias for $1;
	p_len2		alias for $2;
	p_matches	alias for $3;
begin
	return (p_matches * 200 / (p_len1 + p_len2));
end;$_$;


ALTER FUNCTION public.category_synonym__get_similarity(integer, integer, bigint) OWNER TO simone;

--
-- Name: category_synonym__new(character varying, character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.category_synonym__new(character varying, character varying, integer, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
	p_name		alias for $1;
	p_locale	alias for $2;
	p_category_id	alias for $3;
	p_synonym_id	alias for $4;
	v_synonym_id	integer;
begin
	-- get new synonym_id
	if (p_synonym_id is null) then
		v_synonym_id := nextval ('category_synonyms_id_seq');
	else 
		v_synonym_id := p_synonym_id;
	end if;

	-- insert synonym data
	insert into category_synonyms (synonym_id, category_id, locale, name, synonym_p)
	values (v_synonym_id, p_category_id, p_locale, p_name, 't');

	-- insert in synonym index and search results
	PERFORM category_synonym__reindex (v_synonym_id, p_name, p_locale);

	return (v_synonym_id);
end;$_$;


ALTER FUNCTION public.category_synonym__new(character varying, character varying, integer, integer) OWNER TO simone;

--
-- Name: category_synonym__new_cat_trans_trg(); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.category_synonym__new_cat_trans_trg() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
-- trigger function for inserting category translation
declare
    v_synonym_id     integer;
begin
	-- create synonym
    v_synonym_id := category_synonym__new (NEW.name, NEW.locale, NEW.category_id, null);

	-- mark synonym as not editable for users
    update category_synonyms
    set synonym_p = 'f'
    where synonym_id = v_synonym_id;

    return new;
end;$$;


