--
-- Name: content_item__new(character varying, integer, character varying, text, text); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.content_item__new(character varying, integer, character varying, text, text) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
        new__name               alias for $1;
        new__parent_id          alias for $2;  -- default null
        new__title              alias for $3;  -- default null
        new__description        alias for $4;  -- default null
        new__text               alias for $5;  -- default null
begin
