--
-- Name: content_item__unset_live_revision(integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.content_item__unset_live_revision(integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
  unset_live_revision__item_id                alias for $1;  
begin

  update
    cr_items
  set
    live_revision = NULL
  where
    item_id = unset_live_revision__item_id;

  -- if an items publish status is "live", change it to "ready"
  update
    cr_items
  set
    publish_status = 'production'
  where
    publish_status = 'live'
  and
    item_id = unset_live_revision__item_id;

  return 0; 
end;$_$;


