-- Name: content_revision__get_content(integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.content_revision__get_content(integer) RETURNS text
    LANGUAGE plpgsql STABLE STRICT
    AS $_$
declare
  get_content__revision_id            alias for $1;  
  v_storage_type                      varchar;
  v_lob_id                            integer;
  v_data                              text;
begin
       select i.storage_type, r.lob 
         into v_storage_type, v_lob_id
         from cr_items i, cr_revisions r
        where i.item_id = r.item_id 
          and r.revision_id = get_content__revision_id;
        
        if v_storage_type = 'lob' then
           return v_lob_id::text;
        else 
           return content
             from cr_revisions
            where revision_id = get_content__revision_id;
        end if;

end;$_$;


