--
-- Name: content_revision__get_number(integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.content_revision__get_number(integer) RETURNS integer
    LANGUAGE plpgsql STABLE STRICT
    AS $_$
declare
  get_number__revision_id            alias for $1;  
  v_revision                         cr_revisions.revision_id%TYPE;
  v_row_count                        integer default 0;
  rev_cur                            record;
begin
  for rev_cur in select
                   revision_id
                 from 
                   cr_revisions r, acs_objects o
                 where
                   item_id = (select item_id from cr_revisions 
                               where revision_id = get_number__revision_id)
                 and
                   o.object_id = r.revision_id
                 order by
                   o.creation_date
  LOOP
    v_row_count := v_row_count + 1;
    if rev_cur.revision_id = get_number__revision_id then 
       return v_row_count;
       exit;
    end if;
  end LOOP;

  return null;
 
end;$_$;


ALTER FUNCTION public.content_revision__get_number(integer) OWNER TO simone;

