--

CREATE FUNCTION public.content_revision__new(character varying, character varying, timestamp with time zone, character varying, text, integer, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
        new__title              alias for $1;
        new__description        alias for $2;  -- default null
        new__publish_date       alias for $3;  -- default now()
        new__mime_type          alias for $4;  -- default 'text/plain'
        new__text               alias for $5;  -- default ' '
        new__item_id            alias for $6;
        new__package_id         alias for $7;  -- default null
begin
        return content_revision__new(new__title,
                                     new__description,
                                     new__publish_date,
                                     new__mime_type,
                                     null,
                                     new__text,
                                     new__item_id,
                                     null,
                                     now(),
                                     null,
                                     null,
                                     null,
                                     new__package_id
               );

end;$_$;


