CREATE FUNCTION public.content_search__dtrg() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
    perform search_observer__enqueue(old.revision_id,'DELETE');
    return old;
end;$$;


ALTER FUNCTION public.content_search__dtrg() OWNER TO simone;

--
-- Name: content_search__itrg(); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.content_search__itrg() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
if (select live_revision from cr_items where item_id=new.item_id) = new.revision_id and new.publish_date >= current_timestamp then
        perform search_observer__enqueue(new.revision_id,'INSERT');
    end if;
    return new;
end;$$;


ALTER FUNCTION public.content_search__itrg() OWNER TO simone;

--
-- Name: content_search__utrg(); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.content_search__utrg() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
    v_live_revision integer;
begin
    select into v_live_revision live_revision from
        cr_items where item_id=old.item_id;
    if old.revision_id=v_live_revision
      and new.publish_date <= current_timestamp then
        insert into search_observer_queue (
            object_id,
            event
        ) values (
old.revision_id,
            'UPDATE'
        );
    end if;
    return new;
end;$$;


