--
-- Name: dow_to_int(character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.dow_to_int(character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
       dow_to_int__weekday	alias for $1;
       v_dow			integer;
begin
       -- Brute force (what can I say?).
       select (case trim(upper(dow_to_int__weekday))
	             when 'SUNDAY'    then 1
	             when 'SUN'       then 1
		     when 'MONDAY'    then 2
		     when 'MON'	then 2
		     when 'TUESDAY'	then 3
		     when 'TUES'	then 3
		     when 'TUE'	then 3
		     when 'WEDNESDAY' then 4
		     when 'WED'	then 4
		     when 'WEDS'	then 4
		     when 'THURSDAY'  then 5
		     when 'THURS'	then 5
		     when 'THUR'	then 5
		     when 'THU'	then 5
		     when 'FRIDAY'	then 6
		     when 'FRI'	then 6
		     when 'SATURDAY'	then 7
		     when 'SAT'	then 7
		     else -1
		end) into v_dow
       from dual;
	
       if v_dow < 0 
       then 
	   raise exception 'Day of the week unknown';
       end if;

       return v_dow;

end;$_$;


ALTER FUNCTION public.dow_to_int(character varying) OWNER TO simone;

--
-- Name: drop_package(character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.drop_package(package_name character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
       v_rec             record;
       v_drop_cmd        varchar;
       v_pkg_name        varchar;
BEGIN
        raise NOTICE 'DROP PACKAGE: %', package_name;
        v_pkg_name := package_name || '__' || '%';

        for v_rec in select proname 
                       from pg_proc 
                      where proname like v_pkg_name 
                   order by proname 
        LOOP
            raise NOTICE 'DROPPING FUNCTION: %', v_rec.proname;
            v_drop_cmd := get_func_drop_command (v_rec.proname::varchar);
            EXECUTE v_drop_cmd;
        end loop;

        if NOT FOUND then 
          raise NOTICE 'PACKAGE: % NOT FOUND', package_name;
        else
          raise NOTICE 'PACKAGE: %: DROPPED', package_name;
        end if;
        
        return null;

END;
$$;


ALTER FUNCTION public.drop_package(package_name character varying) OWNER TO simone;

