--
-- Name: faq__new_faq(integer, character varying, boolean, character varying, timestamp with time zone, integer, character varying, integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.faq__new_faq(integer, character varying, boolean, character varying, timestamp with time zone, integer, character varying, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
	p_faq_id				alias for $1;
	p_faq_name 			alias for $2;
	p_separate_p		alias for $3;
	p_object_type 	alias for $4;
	p_creation_date	alias for $5;
	p_creation_user alias for $6;
	p_creation_ip		alias for $7;
	p_context_id 		alias for $8;
	v_faq_id 				faqs.faq_id%TYPE;
begin

	v_faq_id := acs_object__new (
		p_faq_id,
		p_object_type,
		p_creation_date,
		p_creation_user,
		p_creation_ip,
		p_context_id,
                't',
                p_faq_name,
                p_context_id );

	insert into faqs
		(faq_id, faq_name,separate_p)
	values
		(v_faq_id, p_faq_name,p_separate_p);

return v_faq_id;

end;$_$;


ALTER FUNCTION public.faq__new_faq(integer, character varying, boolean, character varying, timestamp with time zone, integer, character varying, integer) OWNER TO simone;

--
-- Name: faq__new_q_and_a(integer, integer, character varying, character varying, integer, character varying, timestamp with time zone, integer, character varying, integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.faq__new_q_and_a(integer, integer, character varying, character varying, integer, character varying, timestamp with time zone, integer, character varying, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
	p_entry_id   		alias for $1;				-- default null,
	p_faq_id     		alias for $2;
	p_question   		alias for $3;
	p_answer     		alias for $4;
	p_sort_key   		alias for $5;
	p_object_type 	alias for $6;     		-- default faq_q_and_a
	p_creation_date alias for $7;  --in acs_objects.creation_date%TYPE   default sysdate,
	p_creation_user alias for $8;	 --in acs_objects.creation_user%TYPE   default null,
	p_creation_ip    	alias for $9;		-- in acs_objects.creation_ip%TYPE     default null,
	p_context_id     	alias for $10; 	--in acs_objects.context_id%TYPE      default null
	v_entry_id 			faq_q_and_as.entry_id%TYPE;
	v_package_id 			acs_objects.package_id%TYPE;
begin
        select package_id into v_package_id from acs_objects where object_id = p_faq_id;

	v_entry_id := acs_object__new (
		p_entry_id,
		p_object_type,		
		p_creation_date,
		p_creation_user,
		p_creation_ip,
		p_context_id,
                't',
                p_question,
                v_package_id
  );
	insert into faq_q_and_as
		(entry_id, faq_id, question, answer, sort_key)
	values
		(v_entry_id, p_faq_id, p_question, p_answer, p_sort_key);
  return v_entry_id;

end;$_$;


