--
-- Name: images_f(public.imagesi); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.images_f(p_new public.imagesi) RETURNS void
    LANGUAGE plpgsql
    AS $$
             declare
               v_revision_id integer;
             begin

               select content_revision__new(
                                     p_new.title,
                                     p_new.description,
                                     now(),
                                     p_new.mime_type,
                                     p_new.nls_language,
                                     case when p_new.text is null 
                                              then p_new.data 
                                              else p_new.text
                                           end,
                                     content_symlink__resolve(p_new.item_id),
                                     p_new.revision_id,
                                     now(),
                                     p_new.creation_user, 
                                     p_new.creation_ip,
                                     p_new.object_package_id
                ) into v_revision_id;
                 insert into images ( image_id, height, width ) values (v_revision_id, p_new.height, p_new.width);
    
   return;
   end;$$;


