--

CREATE FUNCTION public.iter_edit_data(character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $_$
declare
   data_in   alias for $1;
   data_ws   date;
   data_form varchar;
   data_test varchar;
   data_out  varchar;
begin
   if length(data_in) = 8
   then
      data_form := 'YYYYMMDD';
   else
      data_form := 'YYYY-MM-DD';
   end if;

   data_ws   := to_date(data_in,data_form);
   data_test := to_char(data_ws,data_form);
   if data_test <> data_in
   then
      return 'Error: date not valid';
   end if;
   data_out  := iter_edit_data(data_ws);
   return data_out;
end;$_$;


