--
-- Name: journal_entry__new(integer, integer, character varying, character varying, timestamp with time zone, integer, character varying, character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.journal_entry__new(integer, integer, character varying, character varying, timestamp with time zone, integer, character varying, character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
  new__journal_id             alias for $1;  -- default null  
  new__object_id              alias for $2;  
  new__action                 alias for $3;  
  new__action_pretty          alias for $4;  -- default null
  new__creation_date          alias for $5;  -- default now()
  new__creation_user          alias for $6;  -- default null
  new__creation_ip            alias for $7;  -- default null
  new__msg                    alias for $8;  -- default null
  v_journal_id                journal_entries.journal_id%TYPE;
begin
	v_journal_id := acs_object__new (
	  new__journal_id,
	  'journal_entry',
	  new__creation_date,
	  new__creation_user,
	  new__creation_ip,
	  new__object_id,
          't',
          new__action,
          null
	);

        insert into journal_entries (
            journal_id, object_id, action, action_pretty, msg
        ) values (
            v_journal_id, new__object_id, new__action, 
            new__action_pretty, new__msg
        );

        return v_journal_id;
     
end;$_$;


ALTER FUNCTION public.journal_entry__new(integer, integer, character varying, character varying, timestamp with time zone, integer, character varying, character varying) OWNER TO simone;

--
-- Name: last_day(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.last_day(timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE plpgsql
    AS $_$
declare
       last_day__somedate	alias for $1;
       v_month			integer;
       v_targetmonth		integer;
       v_date			timestamptz;
       v_targetdate		timestamptz;
begin
	
       -- Initial values
       v_targetdate := last_day__somedate;
       v_targetmonth := extract(month from last_day__somedate);

       -- Add up to 31 days to the given date, stop if month changes.
       FOR i IN 1..31 LOOP

	    v_date := last_day__somedate + to_interval(i,'days');
	    v_month := extract(month from v_date);

	    if v_month != v_targetmonth
	    then
		exit;
	    else
	       v_targetdate := v_date;
	    end if;

       END LOOP;
	
       return v_targetdate;

end;$_$;


ALTER FUNCTION public.last_day(timestamp with time zone) OWNER TO simone;

