--
-- Name: lob_copy(integer, integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.lob_copy(integer, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
        from_id         alias for $1;
        to_id           alias for $2;
begin
	if from_id is null then 
	    raise exception 'lob_copy: attempt to copy null from_id to % to_id',to_id;
        end if;

        insert into lobs (lob_id,refcount) values (to_id,0);

        insert into lob_data
             select to_id as lob_id, segment, byte_len, data
               from lob_data
              where lob_id = from_id;

        return null;

end;$_$;


ALTER FUNCTION public.lob_copy(integer, integer) OWNER TO simone;

--
-- Name: lob_get_data(integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.lob_get_data(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$
declare
        p_lob_id alias for $1;
        v_rec   record;
        v_data  text default '';
begin
        for v_rec in select data, segment from lob_data where lob_id = p_lob_id order by segment 
        loop
            v_data := v_data || v_rec.data;
        end loop;

        return v_data;

end;$_$;


ALTER FUNCTION public.lob_get_data(integer) OWNER TO simone;

