CREATE FUNCTION public.rel_segment__new(integer, character varying, timestamp with time zone, integer, character varying, character varying, character varying, character varying, integer, character varying, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
  new__segment_id        alias for $1;  -- default null  
