--
-- Name: table_exists(character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.table_exists(character varying) RETURNS boolean
    LANGUAGE plpgsql STABLE STRICT
    AS $_$
declare
