--
-- Name: timespan__overlaps_interval_p(integer, integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.timespan__overlaps_interval_p(integer, integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $_$
declare
       overlaps_interval_p__timespan_id   alias for $1;
       overlaps_interval_p__interval_id   alias for $2; -- default null
       v_start_date               timestamptz;
       v_end_date                 timestamptz;
begin
       select start_date, end_date
       into   v_start_date, v_end_date
       from   time_intervals
       where  interval_id = overlaps_interval_p__interval_id;
        
       return timespan__overlaps_p(
                        overlaps_interval_p__timespan_id, 
                        v_start_date, 
                        v_end_date
                        );

end;$_$;


ALTER FUNCTION public.timespan__overlaps_interval_p(integer, integer) OWNER TO simone;

--
-- Name: timespan__overlaps_p(integer, integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.timespan__overlaps_p(integer, integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $_$
declare
       overlaps_p__timespan_1_id   alias for $1;
       overlaps_p__timespan_2_id   alias for $2;
       v_result             boolean;
       rec_timespan                 record;
begin
       -- Loop over 2nd timespan, checking each interval against 1st
       for rec_timespan in 
            select * 
            from timespans
            where timespan_id = overlaps_p__timespan_2_id
       loop
            v_result := timespan__overlaps_interval_p(
                                overlaps_p__timespan_1_id,
                                rec_timespan.interval_id
                                );
            if v_result then
                return true;
            end if;
       end loop;

       return false;

end;$_$;


ALTER FUNCTION public.timespan__overlaps_p(integer, integer) OWNER TO simone;

--
-- Name: timespan__overlaps_p(integer, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.timespan__overlaps_p(integer, timestamp with time zone, timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql
    AS $_$
declare
       overlaps_p__timespan_id     alias for $1;
       overlaps_p__start_date      alias for $2; -- default null,
       overlaps_p__end_date        alias for $3; -- default null
       v_result                    boolean;
       rec_timespan                record;
begin
       -- Loop over each interval in timespan, checking against dates.
       for rec_timespan in
            select * 
            from timespans
            where timespan_id = overlaps_p__timespan_id
       loop
            v_result := time_interval__overlaps_p(
                                rec_timespan.interval_id, 
                                overlaps_p__start_date,
                                overlaps_p__end_date
                                );

            if v_result then
                return true;
            end if;
       end loop;

       return false;

end;$_$;


