--
-- Name: timezone__convert_to_local(integer, character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.timezone__convert_to_local(integer, character varying) RETURNS timestamp with time zone
    LANGUAGE plpgsql STABLE
    AS $_$
declare
  p_tz_id alias for $1;
  p_utc_varchar alias for $2;
  v_base_time timestamptz;
begin

  select "timestamptz" (p_utc_varchar || substr(gmt_offset,1,5)) into v_base_time
  from timezones
  where tz_id = p_tz_id;

  if not found then
    return "timestamptz" (p_utc_varchar || '+00');
  end if;

  return "timestamptz" (p_utc_varchar) + "interval" (gmt_offset || 'seconds')
  from   timezone_rules
  where  tz_id = p_tz_id and v_base_time between utc_start and utc_end;

end;$_$;


ALTER FUNCTION public.timezone__convert_to_local(integer, character varying) OWNER TO simone;

--
-- Name: timezone__convert_to_utc(integer, character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.timezone__convert_to_utc(integer, character varying) RETURNS timestamp with time zone
    LANGUAGE plpgsql
    AS $_$
declare
  p_tz_id alias for $1;
  p_local_varchar alias for $2;
  v_base_time timestamptz;
begin

  select "timestamptz" (p_local_varchar || substr(gmt_offset,1,5)) into v_base_time
  from timezones
  where tz_id = p_tz_id;

  if not found then
    return "timestamptz" (p_local_varchar || '+00');
  end if;

  return "timestamptz" (p_local_varchar) - "interval" (gmt_offset || 'seconds')
  from   timezone_rules
  where  tz_id = p_tz_id and v_base_time between utc_start and utc_end;

end;$_$;


