--
-- Name: tree_increment_key(bit varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.tree_increment_key(bit varying) RETURNS bit varying
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare
    p_child_sort_key                alias for $1;
    v_child_sort_key                integer;
begin
    if p_child_sort_key is null then
        v_child_sort_key := 0;
    else
        v_child_sort_key := tree_leaf_key_to_int(p_child_sort_key) + 1;
    end if;

    return int_to_tree_key(v_child_sort_key);
end;$_$;


