--
-- Name: trigger_type(integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.trigger_type(integer) RETURNS character varying
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare
  tgtype            alias for $1;
  description       varchar;
  sep               varchar;
begin

 if (tgtype & 2) > 0 then
    description := 'BEFORE ';
 else 
    description := 'AFTER ';
 end if;

 sep := '';

 if (tgtype & 4) > 0 then
    description := description || 'INSERT ';
    sep := 'OR ';
 end if;

 if (tgtype & 8) > 0 then
    description := description || sep || 'DELETE ';
    sep := 'OR ';
 end if;

 if (tgtype & 16) > 0 then
    description := description || sep || 'UPDATE ';
    sep := 'OR ';
 end if;

 if (tgtype & 1) > 0 then
    description := description || 'FOR EACH ROW';
 else
    description := description || 'STATEMENT';
 end if;

 return description;

end;$_$;


ALTER FUNCTION public.trigger_type(integer) OWNER TO simone;

