--
-- Name: util__logical_negation(boolean); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.util__logical_negation(boolean) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    AS $_$
declare
        true_or_false alias for $1;
begin
      IF true_or_false is null THEN
        return null;
      ELSE IF true_or_false = 'f' THEN
        return 't';   
      ELSE 
        return 'f';   
      END IF; END IF;
END;$_$;


ALTER FUNCTION public.util__logical_negation(boolean) OWNER TO simone;

--
-- Name: util__multiple_nextval(character varying, integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.util__multiple_nextval(character varying, integer) RETURNS character varying
    LANGUAGE plpgsql
    AS $_$
declare
  v_sequence_name        alias for $1;  
  v_count                alias for $2;  
  a_sequence_values      text default ''; 
  v_rec                  record;
begin
    for counter in 1..v_count loop
        for v_rec in EXECUTE 'select ' || quote_ident(v_sequence_name) || '.nextval as a_seq_val'
        LOOP
           a_sequence_values := a_sequence_values || '','' || v_rec.a_seq_val;
          exit;
        end loop;
    end loop;

    return substr(a_sequence_values, 2);
 
end;$_$;


