--
-- Name: ESTRAZIONE1; Type: VIEW; Schema: public; Owner: simone
--

CREATE VIEW public."ESTRAZIONE1" AS
 SELECT coimaimp.cod_impianto,
    coimaimp.cod_impianto_est,
    coimaimp.cod_potenza,
    coimaimp.potenza,
    coimaimp.potenza_utile,
    coimaimp.data_installaz,
    coimaimp.volimetria_risc,
    coimaimp.n_generatori,
    coimaimp.consumo_annuo,
    coimaimp.cod_cted,
    coimcted.descr_cted,
    coimaimp.stato,
    coimaimp.cod_comune,
    coimcomu.denominazione AS comune,
    coimaimp.cod_provincia AS provincia,
    coimprov.denominazione,
    coimdimp.data_controllo,
    coimdimp.temp_fumi,
    coimdimp.temp_ambi,
    coimdimp.o2,
    coimdimp.co2,
    coimdimp.bacharach,
    coimdimp.co,
    coimdimp.rend_combust,
    coimdimp.flag_status
   FROM ((((public.coimaimp
     LEFT JOIN public.coimcted ON (((coimaimp.cod_cted)::text = (coimcted.cod_cted)::text)))
     JOIN public.coimcomu ON (((coimaimp.cod_comune)::text = (coimcomu.cod_comune)::text)))
     JOIN public.coimprov ON (((coimaimp.cod_provincia)::text = (coimprov.cod_provincia)::text)))
     JOIN public.coimdimp ON (((coimaimp.cod_impianto)::text = (coimdimp.cod_impianto)::text)));


ALTER TABLE public."ESTRAZIONE1" OWNER TO simone;

