--
-- Name: acs_events_dates; Type: VIEW; Schema: public; Owner: simone
--

CREATE VIEW public.acs_events_dates AS
 SELECT e.event_id,
    e.name,
    e.description,
    e.html_p,
    e.status_summary,
    e.activity_id,
    e.timespan_id,
    e.recurrence_id,
    e.related_link_url,
    e.related_link_text,
    e.redirect_to_rel_link_p,
    t.start_date,
    t.end_date
   FROM public.acs_events e,
    public.timespans s,
    public.time_intervals t
  WHERE ((e.timespan_id = s.timespan_id) AND (s.interval_id = t.interval_id));


ALTER TABLE public.acs_events_dates OWNER TO simone;

