    i.item_id,
    i.name,
        CASE
            WHEN (s.target_id IS NULL) THEN 'f'::text
            ELSE 't'::text
        END AS is_symlink,
    COALESCE(s.target_id, i.item_id) AS resolved_id,
    s.label
   FROM (public.cr_items i
     LEFT JOIN public.cr_symlinks s ON ((i.item_id = s.symlink_id)));


