--
-- Name: registered_users; Type: VIEW; Schema: public; Owner: simone
--

CREATE VIEW public.registered_users AS
 SELECT p.email,
    p.url,
    pe.first_names,
    pe.last_name,
    u.user_id,
    u.authority_id,
    u.username,
    u.screen_name,
    u.priv_name,
    u.priv_email,
    u.email_verified_p,
    u.email_bouncing_p,
    u.no_alerts_until,
    u.last_visit,
    u.second_to_last_visit,
    u.n_sessions,
    u.password,
    u.salt,
    u.password_question,
    u.password_answer,
    u.password_changed_date,
    u.auth_token,
    mr.member_state
   FROM public.parties p,
    public.persons pe,
    public.users u,
    public.group_member_map m,
    public.membership_rels mr
  WHERE ((p.party_id = pe.person_id) AND (pe.person_id = u.user_id) AND (u.user_id = m.member_id) AND (m.rel_id = mr.rel_id) AND (m.group_id = public.acs__magic_object_id('registered_users'::character varying)) AND (m.container_id = m.group_id) AND ((m.rel_type)::text = 'membership_rel'::text) AND ((mr.member_state)::text = 'approved'::text) AND (u.email_verified_p = true));


ALTER TABLE public.registered_users OWNER TO simone;

--
-- Name: rel_constraints_violated_one; Type: VIEW; Schema: public; Owner: simone
--

CREATE VIEW public.rel_constraints_violated_one AS
 SELECT c.constraint_id,
    c.constraint_name,
    c.rel_id,
    c.container_id,
    c.party_id,
    c.rel_type,
    c.rel_segment,
    c.rel_side,
    c.required_rel_segment
   FROM (public.constrained_rels1 c
     LEFT JOIN public.rel_segment_party_map rspm ON (((rspm.segment_id = c.required_rel_segment) AND (rspm.party_id = c.container_id))))
  WHERE (rspm.party_id IS NULL);


ALTER TABLE public.rel_constraints_violated_one OWNER TO simone;

--
-- Name: rel_constraints_violated_two; Type: VIEW; Schema: public; Owner: simone
--

CREATE VIEW public.rel_constraints_violated_two AS
 SELECT c.constraint_id,
    c.constraint_name,
    c.rel_id,
    c.container_id,
    c.party_id,
    c.rel_type,
    c.rel_segment,
    c.rel_side,
    c.required_rel_segment
   FROM (public.constrained_rels2 c
     LEFT JOIN public.rel_segment_party_map rspm ON (((rspm.segment_id = c.required_rel_segment) AND (rspm.party_id = c.party_id))))
  WHERE (rspm.party_id IS NULL);


ALTER TABLE public.rel_constraints_violated_two OWNER TO simone;

--
-- Name: rel_seg_approved_member_map; Type: VIEW; Schema: public; Owner: simone
--

CREATE VIEW public.rel_seg_approved_member_map AS
 SELECT rs.segment_id,
    gem.element_id AS member_id,
    gem.rel_id,
    gem.rel_type,
    gem.group_id,
    gem.container_id
   FROM public.membership_rels mr,
    public.group_element_map gem,
    public.rel_segments rs,
    public.acs_object_types o1,
    public.acs_object_types o2
  WHERE ((rs.group_id = gem.group_id) AND ((rs.rel_type)::text = (o2.object_type)::text) AND ((o1.object_type)::text = (gem.rel_type)::text) AND ((o1.tree_sortkey >= o2.tree_sortkey) AND (o1.tree_sortkey <= public.tree_right(o2.tree_sortkey))) AND (mr.rel_id = gem.rel_id) AND ((mr.member_state)::text = 'approved'::text));


ALTER TABLE public.rel_seg_approved_member_map OWNER TO simone;

