-- Name: user_tab_columns; Type: VIEW; Schema: public; Owner: simone
--

CREATE VIEW public.user_tab_columns AS
 SELECT upper((c.relname)::text) AS table_name,
    upper((a.attname)::text) AS column_name,
    upper((t.typname)::text) AS data_type
   FROM pg_class c,
    pg_attribute a,
    pg_type t
  WHERE ((c.oid = a.attrelid) AND (a.atttypid = t.oid) AND (a.attnum > 0));


ALTER TABLE public.user_tab_columns OWNER TO simone;

--
-- Name: user_tab_comments; Type: VIEW; Schema: public; Owner: simone
--

CREATE VIEW public.user_tab_comments AS
 SELECT upper((c.relname)::text) AS table_name,
        CASE
            WHEN (c.relkind = 'r'::"char") THEN 'TABLE'::text
            WHEN (c.relkind = 'v'::"char") THEN 'VIEW'::text
            ELSE (c.relkind)::text
        END AS table_type,
    d.description AS comments
   FROM (pg_class c
     LEFT JOIN pg_description d ON ((c.oid = d.objoid)))
  WHERE (d.objsubid = 0);


ALTER TABLE public.user_tab_comments OWNER TO simone;

