CREATE VIEW public.xowiki_page_live_revision AS
 SELECT p.page_id,
    p.page_order,
    p.creator,
    cr.revision_id,
    cr.item_id,
    cr.title,
    cr.description,
    cr.publish_date,
    cr.mime_type,
    cr.nls_language,
    cr.lob,
    cr.content,
    cr.content_length,
    ci.parent_id,
    ci.name,
    ci.locale,
    ci.live_revision,
    ci.latest_revision,
    ci.publish_status,
    ci.content_type,
    ci.storage_type,
    ci.storage_area_key,
    ci.tree_sortkey,
    ci.max_child_sortkey
